    CONSTRAINT "offering_cycles_check" CHECK ((("valid_to" IS NULL) OR ("valid_from" IS NULL) OR ("valid_to" >= "valid_from"))),
    CONSTRAINT "offering_cycles_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'closed'::"text", 'archived'::"text", 'cancelled'::"text"])))
);
CREATE TABLE IF NOT EXISTS "scholarship"."scopes" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "scholarship_id" "uuid" NOT NULL,
    "scope_type" "text" NOT NULL,
    "provider_id" "uuid",
    "course_id" "uuid",
    "course_collection_id" "uuid",
    "study_level_id" "uuid",
    "field_id" "uuid",
    "country_id" "uuid",
    "campus_id" "uuid",
    "include_exclude" "text" DEFAULT 'include'::"text" NOT NULL,
    "source_id" "uuid",
    "evidence_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cycle_id" "uuid",
    CONSTRAINT "scopes_include_exclude_check" CHECK (("include_exclude" = ANY (ARRAY['include'::"text", 'exclude'::"text"]))),
    CONSTRAINT "scopes_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['provider'::"text", 'course'::"text", 'course_collection'::"text", 'study_level'::"text", 'field_of_study'::"text", 'country'::"text", 'campus'::"text", 'global'::"text"]))),
    CONSTRAINT "scopes_target_shape_check" CHECK (((("scope_type" = 'global'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'provider'::"text") AND ("provider_id" IS NOT NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'course'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NOT NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'course_collection'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NOT NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'study_level'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NOT NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'field_of_study'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NOT NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'country'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NOT NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'campus'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NOT NULL))))
);

