-- view
CREATE OR REPLACE VIEW "security"."layer4_active_blocks" WITH ("security_barrier"='true') AS
 SELECT "id",
    "entity_type",
    "entity_id",
    "block_scope",
    "reason_code",
    "comment",
    "actor_id",
    "actor_email",
    "expires_at",
    "review_at",
    "approval_context",
    "created_at"
   FROM ( SELECT DISTINCT ON ("d"."entity_type", "d"."entity_id", "d"."block_scope") "d"."id",
            "d"."entity_type",
            "d"."entity_id",
            "d"."block_scope",
            "d"."event_type",
            "d"."reason_code",
            "d"."comment",
            "d"."actor_id",
            "d"."actor_email",
            "d"."expires_at",
            "d"."review_at",
            "d"."approval_context",
            "d"."created_at"
           FROM "pipeline"."layer4_block_decisions" "d"
          ORDER BY "d"."entity_type", "d"."entity_id", "d"."block_scope", "d"."created_at" DESC, "d"."id" DESC) "x"
  WHERE (("event_type" = 'block'::"text") AND (("expires_at" IS NULL) OR ("expires_at" > "now"())));
CREATE OR REPLACE VIEW "security"."layer4_search_blocked_courses" WITH ("security_barrier"='true') AS
 SELECT "layer4_active_blocks"."entity_id" AS "course_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("layer4_active_blocks"."block_scope" = 'search'::"text") AND ("layer4_active_blocks"."entity_type" = 'course'::"text"))
UNION
 SELECT "c"."id" AS "course_id"
   FROM ("security"."layer4_active_blocks" "b"
     JOIN "catalogue"."courses" "c" ON (("c"."provider_id" = "b"."entity_id")))
  WHERE (("b"."block_scope" = 'search'::"text") AND ("b"."entity_type" = 'provider'::"text"));
CREATE OR REPLACE VIEW "security"."layer4_search_blocked_providers" WITH ("security_barrier"='true') AS
 SELECT "entity_id" AS "provider_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("block_scope" = 'search'::"text") AND ("entity_type" = 'provider'::"text"));
CREATE OR REPLACE VIEW "security"."layer4_search_blocked_scholarships" WITH ("security_barrier"='true') AS
 SELECT "layer4_active_blocks"."entity_id" AS "scholarship_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("layer4_active_blocks"."block_scope" = 'search'::"text") AND ("layer4_active_blocks"."entity_type" = 'scholarship'::"text"))
UNION
 SELECT "s"."id" AS "scholarship_id"
   FROM ("security"."layer4_active_blocks" "b"
     JOIN "scholarship"."scholarships" "s" ON (("s"."provider_id" = "b"."entity_id")))
  WHERE (("b"."block_scope" = 'search'::"text") AND ("b"."entity_type" = 'provider'::"text"));

